<template>
  <div class="zg-container rules-page">
    <PageHeader title="办理规则" description="对照可靠原文填写适用条件、审批路径和材料；本人确认后即可启用，也可提交正式审核。"><template #actions><el-button @click="openCoverage">规则建设任务（{{ coverage.length }}）</el-button><el-button v-if="canCreate" type="primary" @click="newRule">新建规则</el-button></template></PageHeader>
    <section class="work-panel" v-loading="loading"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="查找规则或依据制度" style="width:280px" /><el-select v-model="status" clearable placeholder="全部状态" style="width:140px" @change="changeStatus"><el-option v-for="(label,value) in statuses" :key="value" :label="label" :value="value" /></el-select><el-select v-model="scenarioFilter" clearable placeholder="全部事项类型" style="width:150px"><el-option v-for="item in scenarios" :key="item.key" :label="item.label" :value="item.key" /></el-select><span class="row-count">{{ filteredRows.length }} 条</span><el-button @click="load">刷新</el-button></div>
      <DataState :error="loadError" :empty="!loading && !filteredRows.length" :empty-title="keyword || status || scenarioFilter ? '没有符合条件的规则' : '尚未建立办理规则'" empty-description="选择可靠依据，由维护者对照原文确认后启用；需要时可提交正式审核。" @retry="load"><template #actions><el-button v-if="keyword || status || scenarioFilter" @click="resetFilters">重置筛选</el-button><el-button v-else-if="canCreate" type="primary" @click="newRule">新建规则</el-button></template>
        <el-table :data="filteredRows" size="small" class="clickable-table" @row-click="openRule"><el-table-column label="规则名称 / 编号" min-width="220" show-overflow-tooltip><template #default="{row}"><strong>{{ ruleDisplayName(row) }}</strong><div v-if="ruleDisplayName(row)!==row.rule_key" class="muted">{{ row.rule_key }}</div></template></el-table-column><el-table-column label="事项类型" width="110"><template #default="{row}">{{ scenarioLabel(row.scenario) }}</template></el-table-column><el-table-column label="适用金额" min-width="180"><template #default="{row}">{{ conditionLabel(row) }}</template></el-table-column><el-table-column label="依据制度" min-width="230" show-overflow-tooltip><template #default="{row}">{{ row.file_title }} · {{ row.clause_no }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="statusTone(row.status)" effect="plain">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button text type="primary" @click.stop="openRule(row)">{{ row.status==='pending_review' && canCreate ? '核对并启用' : canReview && row.status==='pending_review' ? '查看并审核' : '查看详情' }}</el-button></template></el-table-column></el-table>
      </DataState>
    </section>

    <el-drawer v-model="detailVisible" :title="selected ? ruleDisplayName(selected) : '规则详情'" size="min(960px, 95vw)">
      <template v-if="selected"><div class="rule-state"><el-tag :type="statusTone(selected.status)" effect="plain">{{ statusLabel(selected.status) }}</el-tag><span>{{ scenarioLabel(selected.scenario) }}</span><span v-if="ruleDisplayName(selected)!==selected.rule_key">{{ selected.rule_key }}</span></div><div class="rule-detail-grid"><section><h3>规则口径</h3><el-descriptions :column="1" border size="small"><el-descriptions-item label="适用金额">{{ conditionLabel(selected) }}</el-descriptions-item><el-descriptions-item label="适用组织">{{ selected.org_name || orgLabel(selected.org_scope) }}</el-descriptions-item><el-descriptions-item v-if="Object.keys(selected.conditions || {}).length" label="其他条件"><ul class="condition-list"><li v-for="item in conditionEntries(selected.conditions)" :key="item.label"><strong>{{ item.label }}</strong>：{{ item.value }}</li></ul><details><summary>查看完整条件数据</summary><pre class="conditions-text">{{ JSON.stringify(selected.conditions,null,2) }}</pre></details></el-descriptions-item></el-descriptions><h3>审批路径</h3><ol><li v-for="step in selected.approver_path" :key="step">{{ step }}</li></ol><h3>所需材料</h3><ul v-if="selected.required_materials.length"><li v-for="item in selected.required_materials" :key="item">{{ item }}</li></ul><p v-else class="muted">未配置材料清单</p><p v-if="selected.risk_note" class="risk-note">{{ selected.risk_note }}</p><section v-if="selected.review_note"><h3>审核意见</h3><p class="source-text">{{ selected.review_note }}</p></section></section><section class="source-pane"><h3>制度原文</h3><strong>{{ selected.file_title }}</strong><p class="source-label">{{ selected.clause_no }}</p><div v-if="sourceLoading" class="muted">正在加载条款…</div><DataState v-else-if="sourceError" :error="sourceError" @retry="loadSource(selected.file_id,selected.clause_id)" /><p v-else class="source-text">{{ sourceText || '未能定位完整条款，请核对所属制度。' }}</p><el-button text type="primary" @click="router.push(`/clause/${selected.clause_id}`)">查看完整条款页面</el-button></section></div>
        <section v-if="(canReview || canCreate) && selected.status==='pending_review'" class="review-input"><h3>{{ canCreate ? '核对并启用' : '审核决定' }}</h3><el-checkbox v-model="reviewChecked">已核对原文、适用组织、币种金额边界、审批路径和材料。</el-checkbox><p v-if="canCreate" class="muted">本人确认后即可用于事项，不需要切换审核员账号；正式业务审核仍可按需进行。</p><el-input v-model="reviewNote" type="textarea" :rows="3" maxlength="512" show-word-limit placeholder="可填写本人确认说明；正式退回时请明确需要修正的内容。" /><p v-if="reviewError" class="inline-error" role="alert">{{ reviewError }}</p></section>
      </template>
      <template #footer><el-button @click="detailVisible=false">关闭</el-button><template v-if="selected?.status==='pending_review'"><template v-if="canReview"><el-button :loading="reviewing" @click="review(false)">退回修改</el-button><el-button :type="canCreate ? 'default' : 'primary'" :loading="reviewing" :disabled="!reviewChecked || sourceLoading || !!sourceError || !sourceText" @click="review(true)">正式审核通过</el-button></template><el-button v-if="canCreate" type="primary" :loading="reviewing" :disabled="!reviewChecked || sourceLoading || !!sourceError || !sourceText" @click="activate">本人确认启用</el-button></template></template>
    </el-drawer>

    <el-drawer v-model="createVisible" title="新建办理规则" size="min(1080px, 96vw)" :close-on-click-modal="!saving" :show-close="!saving">
      <div class="authoring-grid"><section><h3>选择依据</h3><el-form :model="form" label-width="92px" :disabled="saving"><el-form-item label="依据制度" required><el-select v-model="form.file_id" filterable style="width:100%" @change="changeFile"><el-option v-for="item in currentRegs" :key="item.file_id" :label="item.title + (item.version ? '（' + item.version + '）' : '')" :value="item.file_id" /></el-select></el-form-item><el-form-item label="依据条款" required><el-select v-model="form.clause_id" filterable remote :remote-method="searchUnits" :loading="unitsLoading" style="width:100%" @change="selectUnit"><el-option v-for="item in clauses" :key="item.clause_id" :label="`${item.clause_no} ${item.content.slice(0,40)}`" :value="item.clause_id" /></el-select><div v-if="unitsTotal>80" class="unit-pager"><el-pagination small layout="prev, pager, next" :page-size="80" :total="unitsTotal" :current-page="unitsPage" @current-change="loadUnits" /></div><div class="muted">共 {{ unitsTotal }} 条可引用单元；可输入关键词查找原文。</div></el-form-item><h3>填写办理口径</h3><el-form-item label="规则名称" required><el-input v-model="form.rule_key" maxlength="96" placeholder="用业务人员看得懂的名称，如：境外变更款美元审批" /></el-form-item><el-form-item label="事项类型" required><el-select v-model="form.scenario" style="width:100%"><el-option v-for="item in scenarios" :key="item.key" :label="item.label" :value="item.key" /></el-select></el-form-item><el-form-item label="适用组织"><el-select v-model="form.org_scope" style="width:100%"><el-option label="所有已授权组织" value="/" /><el-option v-for="org in orgUnits" :key="org.org_id" :label="org.name" :value="org.path" /></el-select></el-form-item><el-form-item label="币种条件" :required="!!form.amount_min.trim() || !!form.amount_max.trim()"><el-select v-model="form.currency" clearable placeholder="不按币种判断可留空" style="width:100%"><el-option label="人民币 CNY" value="CNY" /><el-option label="美元 USD" value="USD" /><el-option label="欧元 EUR" value="EUR" /></el-select><div class="muted">无金额边界时可留空，不按币种筛选；填写金额边界时必须选择具体币种。</div></el-form-item><div class="bounds-grid"><el-form-item label="金额下限"><el-input v-model="form.amount_min" placeholder="无下限则留空" /><el-checkbox v-model="form.min_inclusive">包含下限</el-checkbox></el-form-item><el-form-item label="金额上限"><el-input v-model="form.amount_max" placeholder="无上限则留空" /><el-checkbox v-model="form.max_inclusive">包含上限</el-checkbox></el-form-item></div><el-form-item label="审批路径" required><el-input v-model="form.approver_path" type="textarea" :rows="3" placeholder="每行一个审批环节，按办理顺序排列" /></el-form-item><el-form-item label="所需材料"><el-input v-model="form.materials" type="textarea" :rows="3" placeholder="每行一项材料" /></el-form-item><el-form-item label="风险提示"><el-input v-model="form.risk_note" type="textarea" :rows="2" /></el-form-item></el-form><p v-if="createError" class="inline-error" role="alert">{{ createError }}</p></section><aside class="source-pane author-source"><h3>原文对照</h3><template v-if="chosenClause"><strong>{{ currentRegs.find(reg=>reg.file_id===form.file_id)?.title }}</strong><p class="source-label">{{ chosenClause.clause_no }}</p><p class="source-text">{{ chosenClause.content }}</p></template><p v-else class="muted">选择依据制度和条款后，完整原文会显示在这里。所有审批口径应能在原文中找到依据。</p></aside></div>
      <section class="activation-options"><el-radio-group v-model="activationMode" :disabled="saving"><el-radio value="self">本人确认启用</el-radio><el-radio value="review">提交正式审核</el-radio></el-radio-group><p class="muted">{{ activationMode==='self' ? '我对照原文确认适用条件、路径与材料，保存后直接启用并记录本人确认。' : '保存为待审核规则，审核通过后再用于事项办理。' }}</p><el-checkbox v-if="activationMode==='self'" v-model="authorChecked" :disabled="saving || !chosenClause || unitsLoading">我已对照右侧原文，确认条件、路径和材料有明确依据。</el-checkbox></section>
      <template #footer><span class="footer-note">{{ activationMode==='self' ? '请依据原文填写，不补造金额或审批路径。' : '等待正式审核通过后使用。' }}</span><el-button :disabled="saving" @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="activationMode==='self' && (!authorChecked || !chosenClause)" @click="create">{{ activationMode==='self' ? '确认并启用' : '提交正式审核' }}</el-button></template>
    </el-drawer>

    <el-drawer v-model="coverageVisible" title="规则建设任务" size="min(1120px, 96vw)"><div class="toolbar"><span class="muted">候选条款只提供原文信号，必须核对后才能形成草案。</span><el-button v-if="canCreate" :loading="syncing" @click="syncPool">更新建设任务</el-button></div><DataState :error="coverageError" :empty="!coverage.length" empty-title="暂无候选建设任务" empty-description="规则候选来自现行条款；可以手动选取依据建立草案。" @retry="loadCoverage"><el-table :data="coverage" size="small"><el-table-column label="事项" width="110"><template #default="{row}">{{ scenarioLabel(row.scenario) }}</template></el-table-column><el-table-column prop="file_title" label="依据制度" min-width="220" show-overflow-tooltip /><el-table-column prop="clause_no" label="条款" width="90" /><el-table-column prop="excerpt" label="原文摘录" min-width="330" show-overflow-tooltip /><el-table-column label="责任状态" width="130"><template #default="{row}">{{ coverageTask(row)?.assignee_name || taskStatusLabel(coverageTask(row)?.status) }}</template></el-table-column><el-table-column v-if="canCreate" label="操作" width="150"><template #default="{row}"><el-button v-if="coverageTask(row) && !coverageTask(row)?.assignee_id" text @click="claimCandidate(row)">认领</el-button><el-button text type="primary" @click="useCandidate(row)">核对并建草案</el-button></template></el-table-column></el-table></DataState></el-drawer>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useUserStore } from '@/store/user'
import * as ruleApi from '@/api/rule'
import * as clauseApi from '@/api/clause'
import * as regulationApi from '@/api/regulation'
import * as govApi from '@/api/governance'
import PageHeader from '@/components/PageHeader.vue'
import DataState from '@/components/DataState.vue'
const user=useUserStore();const route=useRoute();const router=useRouter();const loading=ref(false);const saving=ref(false);const loadError=ref('');const createError=ref('');const reviewError=ref('');const status=ref('');const keyword=ref('');const scenarioFilter=ref('');const rows=ref<ruleApi.DecisionRuleOut[]>([]);const regs=ref<ruleApi.RuleSource[]>([]);const clauses=ref<ruleApi.RuleSourceUnit[]>([]);const selectedUnit=ref<ruleApi.RuleSourceUnit|null>(null);const unitsTotal=ref(0);const unitsPage=ref(1);const unitsLoading=ref(false);const unitsKeyword=ref('');let unitsVersion=0;const orgUnits=ref<{org_id:string;name:string;path:string}[]>([])
const selected=ref<ruleApi.DecisionRuleOut|null>(null);const detailVisible=ref(false);const createVisible=ref(false);const sourceText=ref('');const sourceLoading=ref(false);const sourceError=ref('');const reviewChecked=ref(false);const reviewNote=ref('');const reviewing=ref(false);let sourceVersion=0
const activationMode=ref<'self'|'review'>('self');const authorChecked=ref(false);const activationNote='维护者本人已对照原文确认适用条件、路径与材料'
const coverage=ref<ruleApi.RuleCoverageCandidate[]>([]);const coverageVisible=ref(false);const coverageError=ref('');const governanceTasks=ref<govApi.GovernanceTask[]>([]);const syncing=ref(false)
const candidateSource=ref<ruleApi.RuleSource|null>(null)
const canCreate=computed(()=>['R3','R4'].includes(user.role));const canReview=computed(()=>['R2','R4'].includes(user.role));const currentRegs=computed(()=>candidateSource.value && !regs.value.some(item=>item.source_kind==='regulation' && item.file_id===candidateSource.value?.file_id) ? [...regs.value,candidateSource.value] : regs.value)
const scenarios=[{key:'contract_change',label:'合同变更'},{key:'payment',label:'付款申请'},{key:'procurement',label:'采购事项'},{key:'safety',label:'安全事项'},{key:'employment',label:'用工事项'}]
const statuses:Record<string,string>={pending_review:'待审核',current:'已启用',rejected:'已退回',retired:'已退役'}
const blankForm=()=>({rule_key:'',scenario:'contract_change',file_id:'',clause_id:'',source_kind:'regulation' as 'regulation'|'asset',asset_version_id:'',org_scope:'/',currency:'',amount_min:'',amount_max:'',min_inclusive:true,max_inclusive:true,approver_path:'',materials:'',risk_note:''})
const form=ref(blankForm());const chosenClause=computed(()=>clauses.value.find(item=>item.clause_id===form.value.clause_id) || (selectedUnit.value?.clause_id===form.value.clause_id ? selectedUnit.value : null))
const filteredRows=computed(()=>{const term=keyword.value.trim().toLowerCase();return rows.value.filter(row=>(!status.value || row.status===status.value) && (!scenarioFilter.value || row.scenario===scenarioFilter.value) && (!term || `${row.rule_key} ${row.file_title} ${row.clause_no}`.toLowerCase().includes(term)))})
function scenarioLabel(value:string){return scenarios.find(item=>item.key===value)?.label || value}
function ruleDisplayName(row:ruleApi.DecisionRuleOut){return /^[a-z][a-z\d_:-]+$/i.test(row.rule_key) ? scenarioLabel(row.scenario)+'办理规则' : row.rule_key}
function statusLabel(value:string){return statuses[value] || value}
function statusTone(value:string):'success'|'warning'|'info'{return value==='current' ? 'success' : ['pending_review','rejected'].includes(value) ? 'warning' : 'info'}
function orgLabel(path:string){return path==='/' ? '所有已授权组织' : orgUnits.value.find(item=>item.path===path)?.name || path}
function conditionLabel(row:ruleApi.DecisionRuleOut){const currency=row.currency==='*' ? '不按币种筛选' : row.currency;const min=row.amount_min_minor===null ? '' : `${row.min_inclusive ? '≥' : '>'}${(row.amount_min_minor/100).toLocaleString('zh-CN')}`;const max=row.amount_max_minor===null ? '' : `${row.max_inclusive ? '≤' : '<'}${(row.amount_max_minor/100).toLocaleString('zh-CN')}`;return `${currency} ${[min,max].filter(Boolean).join(' 且 ') || '无金额边界'}`}
function conditionEntries(conditions:Record<string,unknown>){const labels:Record<string,string>={urgent:'紧急事项',overseas:'境外事项',is_overseas:'境外事项',country:'所在国家',country_scope:'国家范围',procurement_method:'采购方式',employment_type:'用工类型',contract_type:'合同类型',project_type:'项目类型',org_level:'组织层级'};return Object.entries(conditions).map(([key,value])=>({label:labels[key] || (/[\u4e00-\u9fff]/.test(key) ? key : ('其他事实（'+key+'）')),value:Array.isArray(value) ? '满足其一：'+value.map(item=>String(item)).join('、') : typeof value==='boolean' ? value ? '是' : '否' : value && typeof value==='object' ? '复合条件，请展开核对完整数据' : String(value)}))}
function toMinor(value:string):number|undefined{const text=value.trim();if(!text)return undefined;if(!/^\d+(\.\d{1,2})?$/.test(text))throw new Error('金额应为非负数字，最多保留两位小数');const [whole,frac='']=text.split('.');const amount=Number(whole)*100+Number(frac.padEnd(2,'0'));if(!Number.isSafeInteger(amount))throw new Error('金额超出可处理范围');return amount}
let listVersion=0
async function load(){const version=++listVersion;loading.value=true;loadError.value='';try{const result=await ruleApi.listRules(status.value==='pending_review' ? {status:'pending_review'} : undefined);if(version!==listVersion)return;rows.value=result;const id=route.query.id;if(typeof id==='string'){const row=rows.value.find(item=>item.rule_id===id);if(row)await openRule(row,false)}}catch(error:any){if(version===listVersion)loadError.value=error?.message || '规则清单加载失败'}finally{if(version===listVersion)loading.value=false}}
async function loadAuthoring(){try{const [files,orgs]=await Promise.all([ruleApi.sources(),govApi.listOrgUnits()]);regs.value=files.sources;orgUnits.value=orgs}catch(error:any){createError.value=error?.message || '无法加载制度与组织选项'}}
async function loadCoverage(){coverageError.value='';try{const pool=await ruleApi.coverageCandidates();coverage.value=pool.items;if(canCreate.value)governanceTasks.value=(await govApi.listTasks({task_type:'rule_candidate'})).items}catch(error:any){coverageError.value=error?.message || '建设任务加载失败'}}
function changeStatus(){router.replace({path:'/rules',query:status.value==='pending_review' ? {tab:'pending'} : status.value ? {status:status.value} : {}})}
function resetFilters(){keyword.value='';scenarioFilter.value='';status.value='';changeStatus()}
async function openRule(row:ruleApi.DecisionRuleOut,updateRoute=true){selected.value=row;detailVisible.value=true;reviewChecked.value=false;reviewNote.value='';reviewError.value='';if(updateRoute)router.replace({path:'/rules',query:{...route.query,id:row.rule_id}});await loadSource(row.file_id,row.clause_id)}
async function loadSource(_fileId:string,clauseId:string){const version=++sourceVersion;sourceLoading.value=true;sourceText.value='';sourceError.value='';try{const detail=await clauseApi.clauseDetail(clauseId) as {content?:string};if(version===sourceVersion)sourceText.value=detail.content || ''}catch(error:any){if(version===sourceVersion)sourceError.value=error?.message || '制度原文加载失败'}finally{if(version===sourceVersion)sourceLoading.value=false}}
function newRule(){candidateSource.value=null;form.value=blankForm();activationMode.value='self';authorChecked.value=false;clauses.value=[];selectedUnit.value=null;unitsTotal.value=0;unitsKeyword.value='';createError.value='';createVisible.value=true;void loadAuthoring()}
async function changeFile(){form.value.clause_id='';clauses.value=[];selectedUnit.value=null;unitsKeyword.value='';unitsTotal.value=0;const source=currentRegs.value.find(item=>item.file_id===form.value.file_id);form.value.source_kind=source?.source_kind || 'regulation';form.value.asset_version_id=source?.asset_version_id || '';await loadUnits(1)}
async function loadUnits(page:number){if(!form.value.file_id)return;const version=++unitsVersion;unitsPage.value=page;unitsLoading.value=true;createError.value='';try{const result=await ruleApi.sources({source_kind:form.value.source_kind,...(form.value.source_kind==='asset' ? {asset_version_id:form.value.asset_version_id} : {file_id:form.value.file_id}),keyword:unitsKeyword.value || undefined,offset:(page-1)*80,limit:80});if(version===unitsVersion){clauses.value=result.units;unitsTotal.value=result.total}}catch(error:any){if(version===unitsVersion)createError.value=error?.message || '依据条款加载失败'}finally{if(version===unitsVersion)unitsLoading.value=false}}
function searchUnits(term:string){unitsKeyword.value=term;void loadUnits(1)}
function selectUnit(id:string){selectedUnit.value=clauses.value.find(item=>item.clause_id===id) || null}
async function create(){if(saving.value)return;if(activationMode.value==='self' && (!authorChecked.value || !chosenClause.value)){createError.value='请先对照原文并确认适用条件、路径与材料';return;}if(!form.value.rule_key.trim() || !form.value.file_id || !form.value.clause_id || !form.value.approver_path.trim()){createError.value='请填写规则名称、依据条款和审批路径';return}let min:number|undefined;let max:number|undefined;try{min=toMinor(form.value.amount_min);max=toMinor(form.value.amount_max);if(min!==undefined && max!==undefined && min>max)throw new Error('金额下限不能大于上限');if((min!==undefined || max!==undefined) && (!form.value.currency || form.value.currency==='*'))throw new Error('填写金额边界时请选择具体币种，金额不能跨币种比较')}catch(error:any){createError.value=error.message;return}saving.value=true;createError.value='';try{const created=await ruleApi.createRule({activate_now:activationMode.value==='self',activation_note:activationMode.value==='self' ? activationNote : undefined,rule_key:form.value.rule_key.trim(),scenario:form.value.scenario,...(form.value.source_kind==='asset' ? {source_kind:'asset',asset_version_id:form.value.asset_version_id,retrieval_unit_id:chosenClause.value?.retrieval_unit_id || form.value.clause_id} : {source_kind:'regulation',file_id:form.value.file_id,clause_id:form.value.clause_id}),org_scope:form.value.org_scope,currency:form.value.currency || '*',amount_min_minor:min,amount_max_minor:max,min_inclusive:form.value.min_inclusive,max_inclusive:form.value.max_inclusive,approver_path:form.value.approver_path.split('\n').map(item=>item.trim()).filter(Boolean),required_materials:form.value.materials.split('\n').map(item=>item.trim()).filter(Boolean),risk_note:form.value.risk_note.trim() || undefined});createVisible.value=false;await load();await openRule(created);ElMessage.success(activationMode.value==='self' ? '已记录本人确认，规则已启用' : '规则草案已提交正式审核')}catch(error:any){createError.value=error?.message || '规则保存失败，请核对来源和办理口径'}finally{saving.value=false}}
async function review(approved:boolean){if(!selected.value || reviewing.value)return;if(!approved && !reviewNote.value.trim()){reviewError.value='退回时请说明需要修改的内容';return}if(approved && !reviewChecked.value)return;reviewing.value=true;reviewError.value='';try{selected.value=await ruleApi.reviewRule(selected.value.rule_id,{approved,note:reviewNote.value.trim()});await load();ElMessage.success(approved ? '规则已通过审核并生效' : '规则已退回')}catch(error:any){reviewError.value=error?.message || '审核提交失败'}finally{reviewing.value=false}}
async function activate(){if(!selected.value || reviewing.value || !reviewChecked.value || sourceLoading.value || sourceError.value || !sourceText.value)return;reviewing.value=true;reviewError.value='';try{selected.value=await ruleApi.activateRule(selected.value.rule_id,{note:reviewNote.value.trim() || activationNote});await load();ElMessage.success('已记录本人确认，规则已启用')}catch(error:any){reviewError.value=error?.message || '规则启用失败，请核对来源和适用范围'}finally{reviewing.value=false}}
function coverageTask(item:ruleApi.RuleCoverageCandidate){return governanceTasks.value.find(task=>task.clause_id===item.clause_id && task.scenario===item.scenario)}
function taskStatusLabel(value?:string){return ({open:'待认领',in_progress:'处理中',resolved:'已完成',dismissed:'不适用'} as Record<string,string>)[value || ''] || '待同步'}
function openCoverage(){coverageVisible.value=true;void loadCoverage()}
async function syncPool(){syncing.value=true;try{await govApi.syncTasks();await loadCoverage();ElMessage.success('建设任务已更新')}catch(error:any){coverageError.value=error?.message || '任务更新失败'}finally{syncing.value=false}}
async function claimCandidate(item:ruleApi.RuleCoverageCandidate){const task=coverageTask(item);if(!task)return;try{await govApi.actOnTask(task.task_id,{action:'claim'});await loadCoverage();ElMessage.success('任务已认领')}catch(error:any){coverageError.value=error?.message || '认领失败'}}
async function useCandidate(item:ruleApi.RuleCoverageCandidate){newRule();await loadAuthoring();if(!currentRegs.value.some(source=>source.source_kind==='regulation' && source.file_id===item.file_id)){try{const original=await regulationApi.regulationDetail(item.file_id);candidateSource.value={source_kind:'regulation',file_id:item.file_id,title:original.title || item.file_title,version:original.version || ''}}catch(error:any){createError.value=error?.message || '候选制度已不可读取，请刷新建设任务';return}}form.value.scenario=item.scenario;form.value.file_id=item.file_id;await changeFile();form.value.clause_id=item.clause_id;selectedUnit.value=clauses.value.find(unit=>unit.clause_id===item.clause_id) || {source_kind:'regulation',file_id:item.file_id,clause_id:item.clause_id,clause_no:item.clause_no,content:item.excerpt};if(!clauses.value.some(unit=>unit.clause_id===item.clause_id)){try{const full=await clauseApi.clauseDetail(item.clause_id) as {content?:string};selectedUnit.value={...selectedUnit.value,content:full.content || item.excerpt};clauses.value.unshift(selectedUnit.value)}catch(error:any){createError.value=error?.message || '候选原文加载失败'}}coverageVisible.value=false}
watch(()=>route.query,(query)=>{status.value=query.tab==='pending' ? 'pending_review' : typeof query.status==='string' ? query.status : '';if(typeof query.id==='string'){const row=rows.value.find(item=>item.rule_id===query.id);if(row && selected.value?.rule_id!==row.rule_id)void openRule(row,false)}},{immediate:true})
watch(()=>route.query.tab==='pending' || route.query.status==='pending_review',()=>{void load()},{immediate:true})
watch(form,()=>{authorChecked.value=false;createError.value=''},{deep:true})
onMounted(()=>{void loadCoverage();if(canCreate.value)void loadAuthoring()})
</script>
<style scoped>
.activation-options{margin-top:18px;padding:12px 16px;background:var(--zg-panel-soft);border:1px solid var(--zg-border)}.activation-options .el-checkbox{height:auto;line-height:1.7}
.rules-page{display:flex;flex-direction:column;gap:14px}.toolbar{display:flex;gap:10px;align-items:center;padding:12px 16px}.row-count{margin-left:auto;color:var(--zg-text-secondary);font-size:12px}.clickable-table :deep(tr){cursor:pointer}.rule-state{display:flex;gap:12px;align-items:center;margin-bottom:18px;color:var(--zg-text-secondary)}.rule-detail-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px}.source-pane{background:var(--zg-panel-soft);padding:16px;border:1px solid var(--zg-border)}h3{font-size:14px;margin:0 0 12px;padding-top:12px;padding-bottom:9px;border-bottom:1px solid var(--zg-border)}li{line-height:1.8;margin-bottom:4px}ul,ol{padding-left:20px}.source-text{white-space:pre-wrap;line-height:1.85;word-break:break-word}.source-label,.muted{color:var(--zg-text-secondary);font-size:12px;line-height:1.7}.risk-note{padding:12px;background:#fffaf0;color:#80500a;line-height:1.7}.review-input{margin-top:20px;border-top:1px solid var(--zg-border);padding-top:8px}.review-input .el-textarea{margin-top:10px}.inline-error{color:#a33a2b;background:#fff5f2;padding:10px;line-height:1.7}.authoring-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:24px}.author-source{position:sticky;top:0;max-height:calc(100vh - 190px);overflow:auto;align-self:start}.bounds-grid{display:grid;grid-template-columns:1fr 1fr}.footer-note{margin-right:auto;color:var(--zg-text-secondary);font-size:12px}.conditions-text{white-space:pre-wrap;margin:0;font-size:12px}@media(max-width:800px){.rule-detail-grid,.authoring-grid{grid-template-columns:1fr}.author-source{position:static;order:-1;max-height:250px}.toolbar{flex-wrap:wrap}.bounds-grid{grid-template-columns:1fr}.footer-note{display:none}}
</style>
